"use client";

const rand = (n: number) => { const x = Math.sin(n * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x); };
const days = Array.from({ length: 30 * 7 }, (_, i) => { const r = rand(i + 7); return r < 0.25 ? 0 : Math.ceil(r * 4); });
const shades = ["bg-zinc-800", "bg-indigo-500/30", "bg-indigo-500/55", "bg-indigo-500/80", "bg-indigo-500"];

export function ContributionHeatmapTailwind() {
  return (
    <div className="inline-flex flex-col gap-3 rounded-xl border border-zinc-800 bg-zinc-950 p-5 text-zinc-100">
      <p className="text-sm"><span className="font-semibold">Activity</span> <span className="text-zinc-400">in the last 30 weeks</span></p>
      <div role="img" aria-label="Activity heatmap for the last 30 weeks" className="grid grid-flow-col grid-rows-7 gap-[3px]">
        {days.map((l, i) => (
          <span key={i} title={`${l} contributions`} style={{ animationDelay: `${(Math.floor(i / 7) + (i % 7)) * 12}ms` }} className={`size-3 rounded-[3px] ${shades[l]} animate-[pop_.4s_cubic-bezier(.34,1.56,.64,1)_both] hover:ring-1 hover:ring-zinc-100 motion-reduce:animate-none`} />
        ))}
      </div>
      <div aria-hidden="true" className="flex items-center justify-end gap-1 text-[11px] text-zinc-400">Less {shades.map((s) => <span key={s} className={`size-3 rounded-[3px] ${s}`} />)} More</div>
      <style>{`@keyframes pop{from{opacity:0;scale:.3}}`}</style>
    </div>
  );
}
